  "codebook": {
    "clarification": "Code 1 when the release (1) announces federal grants, contracts, projects, funding, designations, disaster declarations, new missions/services, or appointments benefiting the senator's state or constituents, whether the senator says 'I secured' or simply 'announced' the award (the announcement frame itself implies responsibility), including earmarks approved at the committee stage; (2) states the senator authored, sponsored, or championed legislation or specific provisions that were enacted, passed by a chamber, adopted as amendments, or included in an advancing package; (3) states or strongly implies an agency acted after the senator's request, appeal, letter, or intervention; or (4) touts past achievements with delivered results (e.g., benefits increased, programs created, back taxes recovered through oversight). Credit may be shared with colleagues or a whole delegation. The senator's name or a quote alone is insufficient: the text must tie the senator to an achieved outcome.",
    "definition": "Credit-claiming occurs when a senator's press release seeks to generate the belief that the senator is personally responsible, in whole or in part, for a concrete government action or outcome that relevant audiences would consider desirable. Typical objects are federal funds, grants, projects, designations, disaster declarations, saved or gained military missions, appointments, or legislation/provisions that have been enacted, passed, adopted, or administratively implemented.",
    "negative_clarification": "Do not code as credit-claiming: (1) pure position-taking — statements of support or opposition, criticism of the President or other actors, praise of others, and explanations of votes; (2) advocacy or demands for future action (letters, calls, urging, questioning at hearings) where no result has been achieved; (3) introduction or cosponsorship of bills that have not advanced beyond introduction; (4) announcements of meetings, hearings, town halls, or ceremonies; (5) honoring others, commemorations, awards given to constituents, and condolences; (6) welcoming or applauding a decision without claiming a causal role in bringing it about. A useful boundary rule: a bill merely introduced is not an achievement, whereas an amendment adopted, a provision included in a moving package, or passage of one's own bill is claimed as an accomplishment and counts.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "Kennedy only introduces stem-cell/cloning legislation. The bill has not passed and no benefit has been delivered; the extensive policy argument is position-taking in support of a proposal, not credit for an outcome."
      },
      {
        "document_id": "656",
        "explanation": "Kerry attacks the Bush Administration's handling of the Dubai Ports deal and port security. Criticizing an opponent and demanding change is position-taking; no government action is claimed as the senator's achievement."
      },
      {
        "document_id": "918",
        "explanation": "Allard simply announces the time and place of a town meeting. An event notice claims no policy result, funding, or benefit and therefore is not credit-claiming."
      }
    ],
    "positive_examples": [
      {
        "document_id": "2627",
        "explanation": "Headlined 'Talent Secures $1.5 Million,' the release explicitly claims the senator obtained funding for a University of Missouri research center — the canonical case of a senator claiming responsibility for federal dollars delivered to his state."
      },
      {
        "document_id": "2318",
        "explanation": "Durbin's letter states in the first person: 'I helped secure an expedited environmental review' and 'facilitated the return of the project to the national priority list for federal funding,' explicitly claiming responsibility for concrete federal actions benefiting the proposed airport."
      },
      {
        "document_id": "89",
        "explanation": "Dorgan announces a national-center designation for Bismarck State College and notes he authored the law creating the designation, directly linking his legislative action to a delivered benefit for a state institution."
      }
    ]
  }
}
